PRNG SEGMENT ALIGN(32)
; Vectorized xoshiro256**
prng_state dq 4 dup (?, ?, ?, ?)  ; initialized at runtime
PRNG ENDS

.code
; @return ymm0: -\Delta U (Negated for Boltzmann distribution.)
; @param  ymm1: s'_i
; @param  ymm2: f'_i (unused)
;         ymm3: temp/scratch reg.
;         ymm4: s_i, m_i, then (unused)
;         ymm5: f_i, m'_i, then (unused)
;         ymm6: (unused), \Delta s_i, then \Delta m_i
;         ymm7: (unused), \Delta f_i, then (unused)
;         ymm8: s_j, f_j, or m_j
;         ymm9: temp/scratch reg.
deltaU_0_23_0 PROC  ; node[0]
	; skipping -deltaU_Je0
	; skipping -deltaU_Je1
	; skipping -deltaU_Jee
	; skipping -deltaU_b
	; skipping -deltaU_B

	; Phase 1:
	vmovapd ymm4, ymmword ptr [nodes + (0)*SIZEOF_NODE + OFFSETOF_SPIN]  ; load s_i

	; Phase 2:
	vsubpd ymm6, ymm1, ymm4  ; \Delta s_i = s'_i - s_i
	; (ymm4) m_i = s_i since f_i = 0
	; (ymm1) m'_i = s'_i since f'_i = 0

	; -deltaU_A calculation
	vmulpd ymm9, ymm1, ymm1  ; m' Hadamard squared: m'2
	vfnmadd231pd ymm9, ymm4, ymm4  ; ymm9 -= ymm4 * ymm4 -> m'2 - m2
	_vdotp xmm0, ymm0, ymm9, ymmword ptr [L + OFFSETOF_REGION_A], xmm8  ; load A_L (region)

	; -deltaU_J calculation
	; [load group 1]
	; edge: 0_23_0 -> 1_23_0
	_vdotp xmm9, ymm9, ymm6, ymmword ptr [nodes + (1)*SIZEOF_NODE + OFFSETOF_SPIN], xmm3  ; load s_1_23_0 (neighbor)
	; edge: 0_23_0 -> 0_24_0
	_vdotadd xmm9, ymm9, ymm6, ymmword ptr [nodes + (5)*SIZEOF_NODE + OFFSETOF_SPIN], xmm3  ; load s_0_24_0 (neighbor)
	; edge: 0_23_0 -> 0_23_1
	_vdotadd xmm9, ymm9, ymm6, ymmword ptr [nodes + (20)*SIZEOF_NODE + OFFSETOF_SPIN], xmm3  ; load s_0_23_1 (neighbor)
	vfmadd231sd xmm0, xmm9, qword ptr [L_L + OFFSETOF_REGION_J]  ; load J_L_L (region)

	; Phase 3: (skip)

	; -deltaU_D calculation
	; [load group 1]
	; skip. For edge, D is not defined at any level (local, region, nor global).
	; skip. For edge, D is not defined at any level (local, region, nor global).
	; skip. For edge, D is not defined at any level (local, region, nor global).

	ret
deltaU_0_23_0 ENDP

